    System.out.println("NPOINTS " + coord[0].length);

    Model m = ModelUtil.load("m", "D:/comsol_ao_run/comsol_vector_optical_baseline/v2/mode_tracking/material_tracking/out/track_t4e-4.mph");
    System.out.println("LOADED " + "D:/comsol_ao_run/comsol_vector_optical_baseline/v2/mode_tracking/material_tracking/out/track_t4e-4.mph");
    int solnum = 40;

    m.result().numerical().create("pt", "Interp");
